<?php defined('ABSPATH') || exit; $d=$args['data']; ?>
 <?php if(($d['address']||$d['locality']||$d['map'])): ?><section id="property-location" class="dossier-section"><div class="dossier-location-heading"><h2>LOCATION CONTEXT</h2><address><?php echo esc_html($d['address']); ?><?php if($d['address']&&$d['locality']): ?><br><?php endif; ?><?php echo esc_html($d['locality']); ?></address></div>
